#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    long long balance = 0, pieces = 0;
    for (char c : s) {
        balance += (c == 'R') ? 1 : -1;
        if (balance == 0) pieces++;
    }
    cout << pieces << "\n";

    return 0;
}

